        [tierA[2], b[2], c[2], d[2]],
        [tierA[3], b[3], c[3], d[3]]
      ];

      const totals = teams.map(t => t.reduce((s, p) => s + p.hcp, 0));
      const spreads = teams.map(t => Math.max(...t.map(p => p.hcp)) - Math.min(...t.map(p => p.hcp)));
      const scrambles = teams.map(t => calcScrambleHcp(t));

      const maxTotDiff = Math.max(...totals) - Math.min(...totals);
